<?php
session_start();if(!isset($_SESSION['user_id'])||$_SESSION['role']!=='patient'){header('Location: ../auth/login.php');exit();}include('../config/database.php');$user_id=(int)$_SESSION['user_id'];$name=$_SESSION['name'];$pq=mysqli_query($conn,"SELECT id FROM patients WHERE user_id=$user_id LIMIT 1");$p=mysqli_fetch_assoc($pq);$patient_id=(int)$p['id'];$old_id=isset($_GET['id'])?(int)$_GET['id']:0;$oq=mysqli_query($conn,"SELECT a.*,d.department_id,dep.name department_name FROM appointments a JOIN doctors d ON a.doctor_id=d.id JOIN departments dep ON d.department_id=dep.id WHERE a.id=$old_id AND a.patient_id=$patient_id AND a.status='cancelled' LIMIT 1");$old=mysqli_fetch_assoc($oq);if(!$old)die('Cancelled appointment not found.');$error='';$success='';if(isset($_POST['rebook'])){$doctor_id=(int)$_POST['doctor_id'];$date=mysqli_real_escape_string($conn,$_POST['appointment_date']);$time=mysqli_real_escape_string($conn,$_POST['appointment_time']);$reason=mysqli_real_escape_string($conn,trim($_POST['reason']));$leave=mysqli_query($conn,"SELECT id FROM doctor_leaves WHERE doctor_id=$doctor_id AND leave_date='$date' LIMIT 1");$dup=mysqli_query($conn,"SELECT id FROM appointments WHERE patient_id=$patient_id AND doctor_id=$doctor_id AND appointment_date='$date' AND appointment_time='$time' AND status!='cancelled' LIMIT 1");if(mysqli_num_rows($leave))$error='Selected doctor is unavailable on this date.';elseif(mysqli_num_rows($dup))$error='You already have an appointment at this time.';else{$mq=mysqli_query($conn,"SELECT MAX(token_number) max_token FROM appointments WHERE doctor_id=$doctor_id AND appointment_date='$date'");$m=mysqli_fetch_assoc($mq);$token=$m['max_token']?((int)$m['max_token']+1):1;$ok=mysqli_query($conn,"INSERT INTO appointments(token_number,patient_id,doctor_id,appointment_date,appointment_time,reason,status,queue_status) VALUES($token,$patient_id,$doctor_id,'$date','$time','$reason','pending','waiting')");if($ok){$dq=mysqli_query($conn,"SELECT u.name doctor_name FROM doctors d JOIN users u ON d.user_id=u.id WHERE d.id=$doctor_id LIMIT 1");$dr=mysqli_fetch_assoc($dq);$msg=mysqli_real_escape_string($conn,'Your appointment has been rebooked with Dr. '.$dr['doctor_name'].' on '.date('d M Y',strtotime($date)).'. Your token is #'.$token.'.');mysqli_query($conn,"INSERT INTO notifications(user_id,message,type) VALUES($user_id,'$msg','appointment')");$success='Rebooking successful. Your new token is #'.$token.'.';}else$error='Unable to rebook.';}}
$doctors=mysqli_query($conn,"SELECT d.id,d.specialization,d.experience,u.name doctor_name FROM doctors d JOIN users u ON d.user_id=u.id WHERE d.department_id=".(int)$old['department_id']." AND d.id!=".(int)$old['doctor_id']." AND u.status=1 ORDER BY u.name ASC");
?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rebook Appointment | ClinicCare</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/patient.css"></head><body><div class="patient-layout"><aside class="patient-sidebar"><div class="patient-brand"><div class="patient-brand-icon"><i class="fa-solid fa-plus"></i></div><div><h3>ClinicCare</h3><span>Patient Portal</span></div></div><div class="patient-profile"><div class="patient-avatar-small"><?php echo strtoupper(substr($name,0,1));?></div><div class="patient-profile-info"><strong><?php echo htmlspecialchars($name);?></strong><span>Patient</span></div></div><nav class="patient-nav"><div class="patient-nav-heading">MAIN MENU</div><a href="dashboard.php" class="patient-nav-link">Dashboard</a><a href="book_appointment.php" class="patient-nav-link">Book Appointment</a><a href="appointments.php" class="patient-nav-link active">Appointments</a><a href="queue.php" class="patient-nav-link">Live Queue</a><a href="prescriptions.php" class="patient-nav-link">Prescriptions</a><a href="notifications.php" class="patient-nav-link">Notifications</a></nav><div class="patient-sidebar-bottom"><a href="../auth/logout.php" class="patient-logout"><i class="fa-solid fa-right-from-bracket"></i>Logout</a></div></aside><main class="patient-main"><header class="patient-topbar"><div><h1>Rebook Appointment</h1><p>Choose another doctor from the same department.</p></div></header><div class="patient-content"><?php if($error){?><div class="cc-alert cc-alert-danger"><div class="cc-alert-icon" style="background:var(--cc-danger);color:#fff"><i class="fa-solid fa-exclamation"></i></div><?php echo htmlspecialchars($error);?></div><?php } if($success){?><div class="cc-alert cc-alert-success"><div class="cc-alert-icon" style="background:var(--cc-success);color:#fff"><i class="fa-solid fa-check"></i></div><?php echo htmlspecialchars($success);?></div><?php } ?><section class="patient-card"><div class="patient-card-header"><div><h2><?php echo htmlspecialchars($old['department_name']); ?></h2><p>Select an alternative doctor.</p></div></div><div class="patient-card-body"><form method="POST"><div class="cc-form-group"><label class="cc-form-label">Doctor</label><select name="doctor_id" class="cc-select" required><option value="">Select doctor</option><?php while($d=mysqli_fetch_assoc($doctors)){?><option value="<?php echo $d['id'];?>">Dr. <?php echo htmlspecialchars($d['doctor_name']);?> — <?php echo htmlspecialchars($d['specialization']);?> — <?php echo $d['experience'];?> years</option><?php } ?></select></div><div class="row"><div class="col-md-6"><div class="cc-form-group"><label class="cc-form-label">New Date</label><input type="date" name="appointment_date" class="cc-input" min="<?php echo date('Y-m-d');?>" required></div></div><div class="col-md-6"><div class="cc-form-group"><label class="cc-form-label">New Time</label><input type="time" name="appointment_time" class="cc-input" required></div></div></div><div class="cc-form-group"><label class="cc-form-label">Reason</label><textarea class="cc-textarea" name="reason"><?php echo htmlspecialchars($old['reason']?:'');?></textarea></div><button name="rebook" class="patient-primary-btn"><i class="fa-solid fa-repeat"></i>Rebook Appointment</button></form></div></section></div></main></div></body></html>
